`}}return n}function Ra(t){const e=new Map,n=[];for(const s of t)s.constraintName?(e.has(s.constraintName)||e.set(s.constraintName,[]),e.get(s.constraintName).push(s)):n.push([s]);return[...Array.from(e.values()),...n]}function Js(t,e,n){const s=n.filter(r=>r.fromTable.toLowerCase()===e.toLowerCase()&&r.fromSchema.toLowerCase()===t.toLowerCase());if(s.length===0)return"";const i=Ra(s);let o=`
